"""Codex/Astra construction v2. Local experimental study primitives, no LLM calls."""
import contextlib
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import time

ROOT = Path(__file__).resolve().parents[1]
PYTHON = '/opt/homebrew/bin/python3'
ROOT_SHA = '8b8408e5cae9822fe0969afd4a70b408d48e69f750dffb88c253dba8ef167dbe'
SEED = ('MathGKM/Markov.lean', 'MathGKM/Protocol.lean', 'MISSION.md',
        'docs/DESIGN.md', 'lakefile.toml', 'lake-manifest.json', 'lean-toolchain')

class Invalid(ValueError):
    pass

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False)

def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def read(path):
    return json.loads(Path(path).read_text())

def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.next')
    with tmp.open('w') as f:
        f.write(canonical(value) + '\n')
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    fd = os.open(path.parent, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)

def save_state(path, state):
    write(path, {'state': state, 'sha256': digest(state)})

def load_state(path):
    envelope = read(path)
    if digest(envelope['state']) != envelope['sha256']:
        raise Invalid('state integrity mismatch')
    return envelope['state']

@contextlib.contextmanager
def lock(path):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('a') as f:
        try:
            fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise Invalid('study/controller/watchdog already running')
        yield f.fileno()

def inside(root, name):
    p = Path(name)
    if p.is_absolute() or '..' in p.parts or any(x.startswith('.') for x in p.parts):
        raise Invalid('unsafe artifact path')
    result = root/p
    if result.is_symlink() or not result.resolve().is_relative_to(root.resolve()):
        raise Invalid('artifact escaped workspace')
    return result

def inventory(root):
    """Research sources only. Never traverse links, Git, caches or provider state."""
    result = {}
    for folder in ('MathGKM', 'research', 'evidence'):
        base = root/folder
        if not base.exists():
            continue
        for directory, dirs, files in os.walk(base, followlinks=False):
            if Path(directory).is_symlink():
                raise Invalid('symlink research directory')
            for d in dirs:
                if (Path(directory)/d).is_symlink():
                    raise Invalid('symlink research directory')
            dirs[:] = [d for d in dirs if not d.startswith('.') and d != '__pycache__']
            for name in files:
                p = Path(directory)/name
                if p.is_symlink():
                    raise Invalid('symlink research artifact')
                if p.suffix not in ('.olean', '.ilean', '.pyc'):
                    result[str(p.relative_to(root))] = sha(p)
    return result

def snapshot(workspace, target, policy):
    target.mkdir(parents=True, exist_ok=False)
    files = inventory(workspace)
    for name in files:
        p = target/'source'/name
        p.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(workspace/name, p)
    result = {'files': files, 'policy': policy, 'created': time.time()}
    result['binding'] = digest({'files': files, 'policy': policy})
    write(target/'manifest.json', result)
    return result

def verify_snapshot(target):
    m = read(target/'manifest.json')
    if inventory(target/'source') != m['files'] or digest({'files': m['files'], 'policy': m['policy']}) != m['binding']:
        raise Invalid('frozen solver artifact changed')
    return m

def dependencies(workspace):
    target = workspace/'.lake/packages'
    target.mkdir(parents=True, exist_ok=True)
    for p in (ROOT/'.lake/packages').iterdir():
        if not (target/p.name).exists():
            (target/p.name).symlink_to(p.resolve(), target_is_directory=True)

def copy_seed(seed, workspace):
    workspace.mkdir(parents=True, exist_ok=False)
    for name in SEED + ('contract.json',):
        target = workspace/name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(seed/name, target)
    for name in ('.scratch', 'research', 'evidence'):
        (workspace/name).mkdir(exist_ok=True)
    dependencies(workspace)

def clean_contract():
    old = read(ROOT/'contracts/markov-goal.json')
    if old['root_sha256'] != ROOT_SHA or sha(ROOT/old['root_file']) != ROOT_SHA:
        raise Invalid('exact supplied root changed')
    return {**old, 'id': 'published-markov-6-3-clean-v2', 'inherited': [],
            'preference': 'Exact root resolution; autonomous revisable agenda; complexity audit-only.',
            'clean_start': {'historical_results': 'none supplied or imported',
                'historical_exercises': 'not rerun; no exercise evidence claimed',
                'removed_inheritance_paths': old['inherited'],
                'reason': 'User-authorized fresh paired study, not an old-run migration.'}}

def implementation():
    files = sorted((ROOT/'machinery').glob('*.py')) + [ROOT/'.bootstrap/base-permissions.json']
    return {str(p.relative_to(ROOT)): sha(p) for p in files}

"""Fresh paired research studies; experimental policy changes, never Goedel switches.

CLI: freeze, run, stop, status, recover, evaluate, completion, audit-report.
All child calls and evaluation overhead debit the owning arm's frozen allowance.
"""
import argparse
import copy
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import time

from .study_common import (ROOT, PYTHON, SEED, Invalid, canonical, digest, sha, read,
    write, save_state, load_state, lock, inventory, snapshot, verify_snapshot,
    clean_contract, copy_seed, implementation)
from . import study_policy as policy

DEFAULT = {'schema': 'math-gkm.study.v2', 'transport': 'fixture',
    'model': 'gpt-6-astra', 'provider': 'codex-configured-provider',
    'usage_semantics': 'unverified_raw_only', 'rounds': 4, 'episode_rounds': 2,
    'invention_rounds': 1, 'call_seconds': 30, 'adaptation_seconds': 30,
    'arm_seconds': 1200, 'max_calls': 24, 'meta_calls': 8,
    'policy_trials': 1, 'policy_trial_rounds': 2, 'output_bytes': 2097152,
    'validation_seconds': 120, 'failure_limit': 3, 'fixture_policy_trial': False,
    'fixture_behavior': 'normal', 'ablations': []}

def public_receipt(receipt):
    """Evaluation answers and compiler diagnostics never enter research roles."""
    if receipt.get('role') == 'adapter':
        return {k: v for k, v in receipt.items() if k not in ('payload', 'before', 'after')}
    return receipt

def public_comparison(result):
    return {k: v for k, v in result.items() if k not in ('sides', 'outcomes')}

def validate_protocol(p):
    if set(p) != set(DEFAULT) or p['schema'] != DEFAULT['schema']:
        raise Invalid('protocol keys/schema mismatch')
    if p['transport'] not in ('fixture', 'live') or p['model'] != 'gpt-6-astra':
        raise Invalid('only explicitly selected fixture or Astra transport')
    if p['fixture_behavior'] not in ('normal', 'sleep', 'missing', 'exit') or (p['transport'] == 'live' and (p['fixture_behavior'] != 'normal' or p['fixture_policy_trial'])):
        raise Invalid('deterministic fixture behaviors are never live research settings')
    for k in ('rounds', 'episode_rounds', 'call_seconds', 'adaptation_seconds', 'arm_seconds',
              'max_calls', 'meta_calls', 'policy_trial_rounds', 'output_bytes', 'validation_seconds', 'failure_limit'):
        if type(p[k]) is not int or p[k] < 1:
            raise Invalid('invalid positive budget: '+k)
    if not 0 <= p['invention_rounds'] < p['episode_rounds'] or p['policy_trials'] < 0:
        raise Invalid('invention must be a minority of episode rounds')
    if p['call_seconds'] > 1800 or p['adaptation_seconds'] > 1800 or p['validation_seconds'] > 180:
        raise Invalid('call or validation timeout too large')
    if p['usage_semantics'] != 'unverified_raw_only':
        raise Invalid('no provider token normalization has been independently validated')
    if not isinstance(p['ablations'], list):
        raise Invalid('ablations must be precommitted artifact paths')
    for path in p['ablations']:
        from .study_common import inside
        inside(ROOT, path)
        if path in SEED or not path.startswith(('MathGKM/', 'research/')):
            raise Invalid('ablation may remove only an experimental component')

def validate_suite(suite):
    if set(suite) != {'schema', 'selector', 'selection_basis', 'independent', 'tasks'} or suite['schema'] != 'math-gkm.suite.v2':
        raise Invalid('invalid evaluation suite')
    if type(suite['independent']) is not bool or not isinstance(suite['tasks'], list):
        raise Invalid('suite independence must be explicit boolean and tasks a list')
    seen = set()
    for task in suite['tasks']:
        required = {'id', 'statement', 'hypotheses', 'scope', 'source_sha256', 'kind',
                    'interface_type', 'transport_type', 'required_constants'}
        if not required <= set(task) or task['id'] in seen or task['kind'] not in ('holdout', 'regression'):
            raise Invalid('invalid/duplicate structural obligation')
        if not isinstance(task['id'], str) or not task['id'] or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' for c in task['id']):
            raise Invalid('unsafe task id')
        if task['source_sha256'] != clean_contract()['root_sha256']:
            raise Invalid('suite source does not match exact root')
        if not all(isinstance(task[k], str) and task[k] for k in ('statement', 'scope', 'interface_type', 'transport_type')):
            raise Invalid('missing exact obligation or scope')
        if not isinstance(task['hypotheses'], list) or not isinstance(task['required_constants'], list):
            raise Invalid('explicit hypotheses and use dependencies required')
        seen.add(task['id'])
    if suite['tasks'] and (not suite['selector'] or not suite['selection_basis']):
        raise Invalid('suite selection provenance required')

def freeze(directory, config=None, suite=None):
    directory = Path(directory).resolve()
    if not directory.is_relative_to(ROOT) or directory == ROOT:
        raise Invalid('study must be a fresh directory inside this workspace')
    p = {**DEFAULT, **(config or {})}
    validate_protocol(p)
    suite = suite or {'schema': 'math-gkm.suite.v2', 'selector': 'none',
        'selection_basis': 'No independent holdout available; no transfer claim authorized.',
        'independent': False, 'tasks': []}
    validate_suite(suite)
    if p['transport'] == 'live' and any(any(k.startswith('fixture_') for k in t) for t in suite['tasks']):
        raise Invalid('fixture answers cannot enter a live suite')
    directory.mkdir(parents=True, exist_ok=False)
    seed = directory/'seed'
    seed.mkdir()
    for name in SEED:
        target = seed/name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(ROOT/name, target)
    write(seed/'contract.json', clean_contract())
    write(directory/'protocol.json', p)
    write(directory/'evaluation/suite.json', suite)
    seal = {'seed': {name: sha(seed/name) for name in SEED + ('contract.json',)},
        'protocol': digest(p), 'suite': digest(suite), 'implementation': implementation(),
        'dependencies': {x.name: str(x.resolve()) for x in (ROOT/'.lake/packages').iterdir()},
        'baseline_adjustments': ['empty history and agenda; no inherited artifacts',
            'same read-isolated filesystem and resource accounting as exploration',
            'same external independent reviews and withheld evaluation overhead charged',
            'legacy single-agenda prompt/action behavior; no portfolio requirement'],
        'frozen_at': time.time(), 'status': 'experimental construction; no mathematical results'}
    write(directory/'seal.json', seal)
    for mode in ('baseline', 'exploration'):
        arm = directory/'arms'/mode
        copy_seed(seed, arm/'workspace')
        snapshot(arm/'workspace', arm/'snapshots/initial', policy.initial(mode)['policy'])
        save_state(arm/'state.json', {'research': policy.initial(mode), 'round': 0,
            'calls': 0, 'meta_calls': 0, 'seconds': 0., 'status': 'ready',
            'active': None, 'receipts': [], 'policy_trials': 0, 'failures': 0,
            'phase': 'research', 'reviewed_rounds': [], 'evaluations': [],
            'resolution': None, 'receipt_hashes': {}, 'seal_hash': digest(seal)})
    return directory

def verify(directory):
    seal = read(directory/'seal.json')
    if digest(read(directory/'protocol.json')) != seal['protocol'] or digest(read(directory/'evaluation/suite.json')) != seal['suite']:
        raise Invalid('frozen protocol/evaluation suite changed')
    if implementation() != seal['implementation']:
        raise Invalid('implementation changed since freeze; new reviewed study required')
    for name, expected in seal['seed'].items():
        if sha(directory/'seed'/name) != expected:
            raise Invalid('frozen seed changed')
    if {x.name: str(x.resolve()) for x in (ROOT/'.lake/packages').iterdir()} != seal['dependencies']:
        raise Invalid('dependency links changed')
    for mode in ('baseline', 'exploration'):
        arm = directory/'arms'/mode
        state = load_state(arm/'state.json')
        if state['seal_hash'] != digest(seal):
            raise Invalid('seal/state binding mismatch')
        for name, expected in seal['seed'].items():
            if sha(arm/'workspace'/name) != expected:
                raise Invalid('protected arm seed changed')
    return read(directory/'protocol.json')

class Arm:
    def __init__(self, study, mode, fd):
        self.study, self.mode, self.fd = study, mode, fd
        self.root = study/'arms'/mode
        self.workspace = self.root/'workspace'
        self.p = read(study/'protocol.json')
        self.s = load_state(self.root/'state.json')
        self.tick = time.monotonic()

    def save(self):
        now = time.monotonic()
        self.s['controller_active_seconds'] = self.s.get('controller_active_seconds', 0) + now-self.tick
        self.tick = now
        save_state(self.root/'state.json', self.s)

    def stopped(self):
        return (self.study/'STOP.json').exists()

    def permitted(self, role, seconds):
        return (not self.stopped() and self.s['calls'] < self.p['max_calls'] and
            self.s['seconds'] + seconds <= self.p['arm_seconds'] and
            (role not in ('proposer', 'reviewer', 'selector') or self.s['meta_calls'] < self.p['meta_calls']))

    def consume(self, job, receipt):
        if str(job) in self.s['receipts']:
            if self.s.get('receipt_hashes', {}).get(str(job)) != digest(receipt):
                raise Invalid('durable receipt changed after accounting')
            return receipt
        self.s['seconds'] += receipt['elapsed_seconds']
        self.s['receipts'].append(str(job))
        self.s.setdefault('receipt_hashes', {})[str(job)] = digest(receipt)
        self.s['active'] = None
        self.s['failures'] = 0 if receipt['outcome'] == 'completed' else self.s['failures'] + 1
        self.save()
        return receipt

    def recover(self):
        active = self.s['active']
        if not active:
            return
        job = Path(active)
        if (job/'receipt.json').exists():
            return self.consume(job, read(job/'receipt.json'))
        if (job/'process.json').exists():
            pid = read(job/'process.json')['pid']
            try:
                os.kill(pid, 0)
            except ProcessLookupError:
                pass
            else:
                raise Invalid('uncertain worker PID still exists; inspect identity before terminating; no replay')
        spec = read(job/'spec.json')
        receipt = {'outcome': 'uncertain_effects_not_replayed', 'payload': None,
            'elapsed_seconds': spec['seconds'], 'role': spec['role'],
            'usage_raw': [], 'normalized_tokens': None, 'mathematical_resolution': False,
            'request_id': spec['request_id'], 'recovery': 'full reservation charged; inspect retained partial artifacts'}
        write(job/'receipt.json', receipt)
        return self.consume(job, receipt)

    def call(self, key, role, req, workspace=None, readonly=False, seconds=None):
        """Idempotent logical invocation; completed or uncertain effects never replay."""
        job = self.root/'jobs'/key
        if (job/'receipt.json').exists():
            return self.consume(job, read(job/'receipt.json'))
        seconds = seconds or self.p['call_seconds']
        if not self.permitted(role, seconds):
            raise Invalid('resource allowance exhausted or stop requested')
        if job.exists():
            raise Invalid('unreconciled invocation; use recover')
        workspace = workspace or self.workspace
        req = {**req, 'request_id': key}
        spec = {'request_id': key, 'workspace': str(workspace), 'role': role,
            'transport': self.p['transport'], 'model': self.p['model'], 'provider': self.p['provider'],
            'usage_semantics': self.p['usage_semantics'], 'readonly': readonly,
            'seconds': seconds, 'output_bytes': self.p['output_bytes'], 'stop': str(self.study/'STOP.json'),
            'fixture_policy_trial': self.p['fixture_policy_trial'], 'fixture_behavior': self.p['fixture_behavior']}
        write(job/'spec.json', spec)
        write(job/'request.json', req)
        from .study_policy import prompt
        (job/'prompt.txt').write_text(prompt(req) if role in ('proposer', 'researcher', 'reviewer', 'selector') else
            policy.COMMON + '\nAdapt the frozen solver to these exact obligations. Do not change hypotheses or source. '
            'Return solutions keyed by task id with module, term, interface_term and transport_term. '
            'No independent test answers are supplied.\n' + canonical(req))
        self.s['active'] = str(job)
        self.s['calls'] += 1
        if role in ('proposer', 'reviewer', 'selector'):
            self.s['meta_calls'] += 1
        self.save()
        with (job/'watchdog.log').open('ab') as log:
            child = subprocess.Popen([PYTHON, '-m', 'machinery.study_worker', str(job)], cwd=ROOT,
                stdin=subprocess.DEVNULL, stdout=log, stderr=log, start_new_session=True, pass_fds=(self.fd,))
            write(job/'watchdog.json', {'pid': child.pid})
            while child.poll() is None:
                time.sleep(.1)
        return self.recover()

    def role_workspace(self, key, records, source=None):
        workspace = self.root/'roles'/key
        if not workspace.exists():
            copy_seed(self.study/'seed', workspace)
            if source:
                for name in inventory(source):
                    p = workspace/name
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copyfile(source/name, p)
            write(workspace/'inbox/records.json', records)
        elif read(workspace/'inbox/records.json') != records:
            raise Invalid('independent role input changed')
        return workspace

    def checked_findings(self, result, workspace, selector=False):
        if result['outcome'] != 'completed':
            return False
        payload = result['payload']
        refs = payload.get('evidence' if selector else 'findings', [])
        from .study_common import inside
        try:
            return bool(refs) and (not selector or bool(payload.get('reason'))) and all(
                inside(workspace, x['path']).is_file() and
                sha(inside(workspace, x['path'])) == x['sha256'] for x in refs)
        except (Invalid, KeyError, TypeError):
            return False

    def research_round(self):
        r = self.s['round']
        self.archive_sources()
        req = policy.request(self.s['research'], r, self.p)
        if self.mode == 'exploration':
            plan_req = {**req, 'role': 'proposer'}
            planned = self.call(f'plan-{r:04d}', 'proposer', plan_req, readonly=True)
            if planned['outcome'] != 'completed':
                raise Invalid('prospective proposer failed within budget; no trial authorized')
            committed = self.root/'jobs'/f'plan-{r:04d}'/'validated-plan.json'
            if committed.exists():
                binding = read(committed)
                if binding['receipt_hash'] != digest(planned):
                    raise Invalid('committed prospective plan changed')
                staged = binding['research']
            else:
                staged = copy.deepcopy(self.s['research'])
                policy.record(staged, planned['payload'], self.workspace, r, self.p)
                write(committed, {'receipt_hash': digest(planned), 'research': staged})
            req = policy.request(staged, r, self.p)
            req['committed_trial'] = planned['payload']['trial']
            req['prospective_binding'] = digest(planned)
        else:
            req['committed_trial'] = None
        result = self.call(f'round-{r:04d}', 'researcher', req)
        if result['outcome'] == 'completed':
            updated = copy.deepcopy(self.s['research'])
            try:
                if self.mode == 'exploration' and result['payload'].get('trial') != req['committed_trial']:
                    raise Invalid('executed report differs from precommitted trial')
                policy.record(updated, result['payload'], self.workspace, r, self.p)
                updated['next_trial'] = result['payload'].get('trial')
                self.s['research'] = updated
            except (Invalid, KeyError, TypeError) as exc:
                self.s['research']['observations'].append({'round': r, 'validation_failure': str(exc),
                    'status': 'report_rejected; no theorem or refutation established'})
        else:
            self.s['research']['observations'].append({'round': r, 'outcome': result['outcome'],
                'meaning': 'failure within budget; no unprovability conclusion'})
        write(self.workspace/f'history/round-{r:04d}.json', result)
        target = self.root/'snapshots'/f'round-{r:04d}'
        if not target.exists():
            snapshot(self.workspace, target, self.s['research']['policy'])
        else:
            verify_snapshot(target)
        self.archive_sources()
        self.s['round'] += 1
        self.s['phase'] = 'review' if self.s['round'] % self.p['episode_rounds'] == 0 or self.s['round'] == self.p['rounds'] else 'research'
        self.save()
        claim = result.get('payload', {}).get('completion') if result['outcome'] == 'completed' else None
        if claim:
            from .study_completion import check
            checked = check(self, claim)
            write(self.root/f'completion-claims/round-{r:04d}.json', {'claim': claim, 'result': checked})

    def archive_sources(self):
        """All old mathematical artifacts remain available read-only to their arm."""
        files = inventory(self.workspace)
        for name, hashed in files.items():
            target = self.workspace/'history/objects'/hashed
            if not target.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(self.workspace/name, target)
        write(self.workspace/f'history/manifests/round-{self.s["round"]:04d}.json', files)

    def review(self):
        r = self.s['round']
        if r in self.s['reviewed_rounds']:
            self.s['phase'] = 'research'
            self.save()
            return
        candidate = self.s['research']['pending_policy']
        committed = self.root/f'review-inputs/review-{r}.json'
        if committed.exists():
            frozen = read(committed)
            records, trial = frozen['records'], frozen['trial']
        else:
            records = {'round': r, 'receipts': [public_receipt(read(Path(p)/'receipt.json')) for p in self.s['receipts']],
                'decisions': self.s['research']['decisions'], 'evaluations': self.s['evaluations']}
            trial = None
            if candidate and self.s['policy_trials'] < self.p['policy_trials']:
                trial = self.policy_trial(candidate)
                records['policy_comparison'] = public_comparison(trial)
            write(committed, {'records': records, 'trial': trial})
        ws = self.role_workspace(f'review-{r}', records, self.workspace)
        result = self.call(f'review-{r}', 'reviewer', {'role': 'reviewer', 'records': 'inbox/records.json'}, ws, True)
        valid = self.checked_findings(result, ws)
        selection_records = {'review': result, 'review_artifact_refs_valid': valid, 'comparison': public_comparison(trial) if trial else None}
        sel_ws = self.role_workspace(f'select-{r}', selection_records)
        selected = self.call(f'select-{r}', 'selector', {'role': 'selector', 'records': 'inbox/records.json'}, sel_ws, True)
        accepted = (valid and self.checked_findings(selected, sel_ws, True) and
            selected['payload'].get('choice') == 'candidate' and trial and trial.get('eligible'))
        if accepted:
            self.s['research']['policy'] = candidate['policy']
        write(self.root/f'decisions/review-{r}.json', {'accepted_experimental_change': bool(accepted),
            'candidate': candidate, 'review': result, 'selection': selected,
            'certified_switch': False, 'comparison': trial})
        self.s['research']['pending_policy'] = None
        self.s['reviewed_rounds'].append(r)
        self.s['phase'] = 'research'
        self.save()

    def policy_trial(self, candidate):
        """Two bounded multi-round continuations from identical current artifacts.

        Branch calls, adaptations, compilation and independent reviews share the
        parent arm allowance. No branch can read another branch or its answers.
        """
        key = f'policy-{candidate["hash"][:16]}-r{self.s["round"]}'
        destination = self.root/'policy_trials'/key
        if (destination/'result.json').exists():
            if key not in self.s.get('completed_policy_trials', []):
                self.s.setdefault('completed_policy_trials', []).append(key)
                self.s['policy_trials'] = len(self.s['completed_policy_trials'])
                self.save()
            return read(destination/'result.json')
        calls = 2*self.p['policy_trial_rounds']*(2 if self.mode == 'exploration' else 1)
        budget = calls*self.p['call_seconds']
        if self.s['seconds'] + budget > self.p['arm_seconds']:
            return {'eligible': False, 'status': 'insufficient_predetermined_continuation_budget'}
        if self.s['calls'] + calls > self.p['max_calls'] or (self.mode == 'exploration' and self.s['meta_calls'] + 2*self.p['policy_trial_rounds'] + 2 > self.p['meta_calls']):
            return {'eligible': False, 'status': 'insufficient_predetermined_call_or_meta_budget'}
        seed = destination/'before'
        if not seed.exists():
            snapshot(self.workspace, seed, self.s['research']['policy'])
        before = verify_snapshot(seed)
        outcomes = {}
        for side, p in [('incumbent', self.s['research']['policy']), ('candidate', candidate['policy'])]:
            ws = self.root/'roles'/f'{key}-{side}'
            if not ws.exists():
                copy_seed(self.study/'seed', ws)
                for name in before['files']:
                    target = ws/name
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copyfile(seed/'source'/name, target)
            local = copy.deepcopy(self.s['research'])
            local['policy'] = p
            local['pending_policy'] = None
            receipts = []
            for n in range(self.p['policy_trial_rounds']):
                req = policy.request(local, n, self.p)
                req['comparison_branch'] = 'blinded-policy-continuation'
                if local['mode'] != 'baseline':
                    plan = self.call(f'{key}-{side}-plan-{n}', 'proposer', {**req, 'role': 'proposer'}, ws, True)
                    if plan['outcome'] != 'completed':
                        raise Invalid('branch prospective proposer failed within budget')
                    staged = copy.deepcopy(local)
                    policy.record(staged, plan['payload'], ws, n, self.p)
                    req = policy.request(staged, n, self.p)
                    req['committed_trial'] = plan['payload']['trial']
                result = self.call(f'{key}-{side}-{n}', 'researcher', req, ws)
                receipts.append(result)
                if result['outcome'] == 'completed':
                    # Record branch history; errors remain evidence, no fabricated success.
                    try:
                        policy.record(local, result['payload'], ws, n, self.p)
                    except (Invalid, KeyError, TypeError):
                        pass
            target = destination/side
            if not target.exists():
                snapshot(ws, target, p)
            outcomes[side] = {'snapshot': str(target), 'receipts': receipts}
        from .study_transfer import evaluate_pair
        comparison = evaluate_pair(self, Path(outcomes['incumbent']['snapshot']), Path(outcomes['candidate']['snapshot']), key)
        result = {'status': 'experimental finite-horizon comparison', 'seed_binding': before['binding'],
            'rounds_each': self.p['policy_trial_rounds'], 'outcomes': outcomes,
            'comparison': public_comparison(comparison), 'eligible': comparison['eligible'], 'certified_switch': False}
        write(destination/'result.json', result)
        self.s.setdefault('completed_policy_trials', []).append(key)
        self.s['policy_trials'] = len(self.s['completed_policy_trials'])
        self.save()
        return result


    def run(self):
        if self.s['resolution']:
            return
        self.recover()
        self.s['status'] = 'running'
        self.save()
        while self.s['round'] < self.p['rounds'] or self.s['phase'] == 'review':
            if self.stopped():
                self.s['status'] = 'stopped'
                break
            if self.s['failures'] >= self.p['failure_limit']:
                self.s['status'] = 'operationally_blocked'
                break
            try:
                if self.s['phase'] == 'review':
                    self.review()
                else:
                    self.research_round()
                verify(self.study)
            except Invalid as exc:
                self.s['status'] = 'stopped' if self.stopped() else 'bounded_or_blocked'
                self.s['reason'] = str(exc)
                break
        else:
            self.s['status'] = 'finite_budget_finished; root_open'
            from .study_transfer import evaluate_pair
            try:
                final = self.root/'snapshots'/f'round-{self.s["round"]-1:04d}'
                result = evaluate_pair(self, self.root/'snapshots/initial', final, f'final-{self.s["round"]}')
                self.s['final_evaluation'] = public_comparison(result)
                from .study_transfer import ablate
                for artifact in self.p['ablations']:
                    ablate(self, final, artifact)
            except Invalid as exc:
                self.s['final_evaluation'] = {'status': 'not_demonstrated_within_budget', 'reason': str(exc)}
        self.save()

def status(directory):
    result = {'study': str(directory), 'stop_requested': (directory/'STOP.json').exists(), 'arms': {}}
    try:
        with lock(directory/'controller.lock'):
            active = False
    except Invalid:
        active = True
    result['controller_or_watchdog_active'] = active
    for mode in ('baseline', 'exploration'):
        s = load_state(directory/'arms'/mode/'state.json')
        result['arms'][mode] = {k: s[k] for k in ('status', 'round', 'calls', 'meta_calls', 'seconds', 'active', 'phase', 'resolution')}
        if s['status'] == 'running' and not active:
            result['arms'][mode]['status'] = 'interrupted; recover without replay'
    return result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    f = sub.add_parser('freeze')
    f.add_argument('--study', type=Path, required=True)
    f.add_argument('--config', type=Path)
    f.add_argument('--suite', type=Path)
    for command in ('run', 'recover', 'status', 'stop', 'evaluate'):
        p = sub.add_parser(command)
        p.add_argument('--study', type=Path, required=True)
        if command in ('run', 'evaluate'):
            p.add_argument('--arm', choices=['both', 'baseline', 'exploration'], default='both')
        if command == 'run':
            p.add_argument('--resume', action='store_true')
            p.add_argument('--detach', action='store_true')
    args = parser.parse_args()
    directory = args.study.resolve()
    try:
        if args.command == 'freeze':
            freeze(directory, read(args.config) if args.config else None, read(args.suite) if args.suite else None)
        elif args.command == 'stop':
            write(directory/'STOP.json', {'requested': time.time()})
        elif args.command == 'status':
            print(canonical(status(directory)))
            return
        else:
            verify(directory)
            if args.command == 'run' and args.detach:
                argv = [PYTHON, '-m', 'machinery.study', 'run', '--study', str(directory), '--arm', args.arm]
                if args.resume:
                    argv.append('--resume')
                with (directory/'controller.log').open('ab') as log:
                    p = subprocess.Popen(argv, cwd=ROOT, stdout=log, stderr=log, stdin=subprocess.DEVNULL, start_new_session=True)
                print(canonical({'controller_pid': p.pid, 'study': str(directory)}))
                return
            with lock(directory/'controller.lock') as fd:
                if args.command == 'run' and args.resume:
                    (directory/'STOP.json').unlink(missing_ok=True)
                def stop_signal(signum, frame):
                    write(directory/'STOP.json', {'signal': signum, 'time': time.time()})
                signal.signal(signal.SIGTERM, stop_signal)
                signal.signal(signal.SIGINT, stop_signal)
                modes = ('baseline', 'exploration') if getattr(args, 'arm', 'both') == 'both' else (args.arm,)
                for mode in modes:
                    arm = Arm(directory, mode, fd)
                    if args.command == 'recover':
                        arm.recover()
                    elif args.command == 'run':
                        arm.run()
                    else:
                        from .study_transfer import evaluate_pair
                        final = arm.root/'snapshots'/f'round-{arm.s["round"]-1:04d}'
                        result = evaluate_pair(arm, arm.root/'snapshots/initial', final, f'final-{arm.s["round"]}')
                        print(canonical(result))
        print(canonical(status(directory)))
    except (Invalid, OSError, KeyError, TypeError) as exc:
        parser.exit(2, f'{type(exc).__name__}: {exc}\n')

if __name__ == '__main__':
    main()

"""Fresh paired research studies; experimental policy changes, never Goedel switches.

CLI: freeze, run, stop, status, recover, evaluate, completion, audit-report.
All child calls and evaluation overhead debit the owning arm's frozen allowance.
"""
import argparse
import copy
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import time

from .study_common import (ROOT, PYTHON, SEED, Invalid, canonical, digest, sha, read,
    write, save_state, load_state, lock, inventory, snapshot, verify_snapshot,
    clean_contract, copy_seed, implementation)
from . import study_policy as policy

DEFAULT = {'schema': 'math-gkm.study.v2', 'transport': 'fixture',
    'model': 'gpt-6-astra', 'provider': 'codex-configured-provider',
    'usage_semantics': 'unverified_raw_only', 'rounds': 4, 'episode_rounds': 2,
    'invention_rounds': 1, 'call_seconds': 30, 'adaptation_seconds': 30,
    'arm_seconds': 1200, 'max_calls': 24, 'meta_calls': 8,
    'policy_trials': 1, 'policy_trial_rounds': 2, 'output_bytes': 2097152,
    'validation_seconds': 120, 'failure_limit': 3, 'fixture_policy_trial': False,
    'fixture_behavior': 'normal', 'ablations': []}

def public_receipt(receipt):
    """Evaluation answers and compiler diagnostics never enter research roles."""
    if receipt.get('role') == 'adapter':
        return {k: v for k, v in receipt.items() if k not in ('payload', 'before', 'after')}
    return receipt

def public_comparison(result):
    return {k: v for k, v in result.items() if k not in ('sides', 'outcomes')}

def validate_protocol(p):
    if set(p) != set(DEFAULT) or p['schema'] != DEFAULT['schema']:
        raise Invalid('protocol keys/schema mismatch')
    if p['transport'] not in ('fixture', 'live') or p['model'] != 'gpt-6-astra':
        raise Invalid('only explicitly selected fixture or Astra transport')
    if p['fixture_behavior'] not in ('normal', 'sleep', 'missing', 'exit') or (p['transport'] == 'live' and (p['fixture_behavior'] != 'normal' or p['fixture_policy_trial'])):
        raise Invalid('deterministic fixture behaviors are never live research settings')
    for k in ('rounds', 'episode_rounds', 'call_seconds', 'adaptation_seconds', 'arm_seconds',
              'max_calls', 'meta_calls', 'policy_trial_rounds', 'output_bytes', 'validation_seconds', 'failure_limit'):
        if type(p[k]) is not int or p[k] < 1:
            raise Invalid('invalid positive budget: '+k)
    if not 0 <= p['invention_rounds'] < p['episode_rounds'] or p['policy_trials'] < 0:
        raise Invalid('invention must be a minority of episode rounds')
    if p['call_seconds'] > 1800 or p['adaptation_seconds'] > 1800 or p['validation_seconds'] > 180:
        raise Invalid('call or validation timeout too large')
    if p['usage_semantics'] != 'unverified_raw_only':
        raise Invalid('no provider token normalization has been independently validated')
    if not isinstance(p['ablations'], list):
        raise Invalid('ablations must be precommitted artifact paths')
    for path in p['ablations']:
        from .study_common import inside
        inside(ROOT, path)
        if path in SEED or not path.startswith(('MathGKM/', 'research/')):
            raise Invalid('ablation may remove only an experimental component')

def validate_suite(suite):
    if set(suite) != {'schema', 'selector', 'selection_basis', 'independent', 'tasks'} or suite['schema'] != 'math-gkm.suite.v2':
        raise Invalid('invalid evaluation suite')
    if type(suite['independent']) is not bool or not isinstance(suite['tasks'], list):
        raise Invalid('suite independence must be explicit boolean and tasks a list')
    seen = set()
    for task in suite['tasks']:
        required = {'id', 'statement', 'hypotheses', 'scope', 'source_sha256', 'kind',
                    'interface_type', 'transport_type', 'required_constants'}
        if not required <= set(task) or task['id'] in seen or task['kind'] not in ('holdout', 'regression'):
            raise Invalid('invalid/duplicate structural obligation')
        if not isinstance(task['id'], str) or not task['id'] or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' for c in task['id']):
            raise Invalid('unsafe task id')
        if task['source_sha256'] != clean_contract()['root_sha256']:
            raise Invalid('suite source does not match exact root')
        if not all(isinstance(task[k], str) and task[k] for k in ('statement', 'scope', 'interface_type', 'transport_type')):
            raise Invalid('missing exact obligation or scope')
        if not isinstance(task['hypotheses'], list) or not isinstance(task['required_constants'], list):
            raise Invalid('explicit hypotheses and use dependencies required')
        seen.add(task['id'])
    if suite['tasks'] and (not suite['selector'] or not suite['selection_basis']):
        raise Invalid('suite selection provenance required')

def freeze(directory, config=None, suite=None):
    directory = Path(directory).resolve()
    if not directory.is_relative_to(ROOT) or directory == ROOT:
        raise Invalid('study must be a fresh directory inside this workspace')
    p = {**DEFAULT, **(config or {})}
    validate_protocol(p)
    suite = suite or {'schema': 'math-gkm.suite.v2', 'selector': 'none',
        'selection_basis': 'No independent holdout available; no transfer claim authorized.',
        'independent': False, 'tasks': []}
    validate_suite(suite)
    if p['transport'] == 'live' and any(any(k.startswith('fixture_') for k in t) for t in suite['tasks']):
        raise Invalid('fixture answers cannot enter a live suite')
    directory.mkdir(parents=True, exist_ok=False)
    seed = directory/'seed'
    seed.mkdir()
    for name in SEED:
        target = seed/name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(ROOT/name, target)
    write(seed/'contract.json', clean_contract())
    write(directory/'protocol.json', p)
    write(directory/'evaluation/suite.json', suite)
    seal = {'seed': {name: sha(seed/name) for name in SEED + ('contract.json',)},
        'protocol': digest(p), 'suite': digest(suite), 'implementation': implementation(),
        'dependencies': {x.name: str(x.resolve()) for x in (ROOT/'.lake/packages').iterdir()},
        'baseline_adjustments': ['empty history and agenda; no inherited artifacts',
            'same read-isolated filesystem and resource accounting as exploration',
            'same external independent reviews and withheld evaluation overhead charged',
            'legacy single-agenda prompt/action behavior; no portfolio requirement'],
        'frozen_at': time.time(), 'status': 'experimental construction; no mathematical results'}
    write(directory/'seal.json', seal)
    for mode in ('baseline', 'exploration'):
        arm = directory/'arms'/mode
        copy_seed(seed, arm/'workspace')
        snapshot(arm/'workspace', arm/'snapshots/initial', policy.initial(mode)['policy'])
        save_state(arm/'state.json', {'research': policy.initial(mode), 'round': 0,
            'calls': 0, 'meta_calls': 0, 'seconds': 0., 'status': 'ready',
            'active': None, 'receipts': [], 'policy_trials': 0, 'failures': 0,
            'phase': 'research', 'reviewed_rounds': [], 'evaluations': [],
            'resolution': None, 'receipt_hashes': {}, 'seal_hash': digest(seal)})
    return directory

def verify(directory):
    seal = read(directory/'seal.json')
    if digest(read(directory/'protocol.json')) != seal['protocol'] or digest(read(directory/'evaluation/suite.json')) != seal['suite']:
        raise Invalid('frozen protocol/evaluation suite changed')
    if implementation() != seal['implementation']:
        raise Invalid('implementation changed since freeze; new reviewed study required')
    for name, expected in seal['seed'].items():
        if sha(directory/'seed'/name) != expected:
            raise Invalid('frozen seed changed')
    if {x.name: str(x.resolve()) for x in (ROOT/'.lake/packages').iterdir()} != seal['dependencies']:
        raise Invalid('dependency links changed')
    for mode in ('baseline', 'exploration'):
        arm = directory/'arms'/mode
        state = load_state(arm/'state.json')
        if state['seal_hash'] != digest(seal):
            raise Invalid('seal/state binding mismatch')
        for name, expected in seal['seed'].items():
            if sha(arm/'workspace'/name) != expected:
                raise Invalid('protected arm seed changed')
    return read(directory/'protocol.json')

class Arm:
    def __init__(self, study, mode, fd):
        self.study, self.mode, self.fd = study, mode, fd
        self.root = study/'arms'/mode
        self.workspace = self.root/'workspace'
        self.p = read(study/'protocol.json')
        self.s = load_state(self.root/'state.json')
        self.tick = time.monotonic()

    def save(self):
        now = time.monotonic()
        self.s['controller_active_seconds'] = self.s.get('controller_active_seconds', 0) + now-self.tick
        self.tick = now
        save_state(self.root/'state.json', self.s)

    def stopped(self):
        return (self.study/'STOP.json').exists()

    def permitted(self, role, seconds):
        return (not self.stopped() and self.s['calls'] < self.p['max_calls'] and
            self.s['seconds'] + seconds <= self.p['arm_seconds'] and
            (role not in ('proposer', 'reviewer', 'selector') or self.s['meta_calls'] < self.p['meta_calls']))

    def consume(self, job, receipt):
        if str(job) in self.s['receipts']:
            if self.s.get('receipt_hashes', {}).get(str(job)) != digest(receipt):
                raise Invalid('durable receipt changed after accounting')
            return receipt
        self.s['seconds'] += receipt['elapsed_seconds']
        self.s['receipts'].append(str(job))
        self.s.setdefault('receipt_hashes', {})[str(job)] = digest(receipt)
        self.s['active'] = None
        self.s['failures'] = 0 if receipt['outcome'] == 'completed' else self.s['failures'] + 1
        self.save()
        return receipt

    def recover(self):
        active = self.s['active']
        if not active:
            return
        job = Path(active)
        if (job/'receipt.json').exists():
            return self.consume(job, read(job/'receipt.json'))
        if (job/'process.json').exists():
            pid = read(job/'process.json')['pid']
            try:
                os.kill(pid, 0)
            except ProcessLookupError:
                pass
            else:
                raise Invalid('uncertain worker PID still exists; inspect identity before terminating; no replay')
        spec = read(job/'spec.json')
        receipt = {'outcome': 'uncertain_effects_not_replayed', 'payload': None,
            'elapsed_seconds': spec['seconds'], 'role': spec['role'],
            'usage_raw': [], 'normalized_tokens': None, 'mathematical_resolution': False,
            'request_id': spec['request_id'], 'recovery': 'full reservation charged; inspect retained partial artifacts'}
        write(job/'receipt.json', receipt)
        return self.consume(job, receipt)

    def call(self, key, role, req, workspace=None, readonly=False, seconds=None):
        """Idempotent logical invocation; completed or uncertain effects never replay."""
        job = self.root/'jobs'/key
        if (job/'receipt.json').exists():
            return self.consume(job, read(job/'receipt.json'))
        seconds = seconds or self.p['call_seconds']
        if not self.permitted(role, seconds):
            raise Invalid('resource allowance exhausted or stop requested')
        if job.exists():
            raise Invalid('unreconciled invocation; use recover')
        workspace = workspace or self.workspace
        req = {**req, 'request_id': key}
        spec = {'request_id': key, 'workspace': str(workspace), 'role': role,
            'transport': self.p['transport'], 'model': self.p['model'], 'provider': self.p['provider'],
            'usage_semantics': self.p['usage_semantics'], 'readonly': readonly,
            'seconds': seconds, 'output_bytes': self.p['output_bytes'], 'stop': str(self.study/'STOP.json'),
            'fixture_policy_trial': self.p['fixture_policy_trial'], 'fixture_behavior': self.p['fixture_behavior']}
        write(job/'spec.json', spec)
        write(job/'request.json', req)
        from .study_policy import prompt
        (job/'prompt.txt').write_text(prompt(req) if role in ('proposer', 'researcher', 'reviewer', 'selector') else
            policy.COMMON + '\nAdapt the frozen solver to these exact obligations. Do not change hypotheses or source. '
            'Return solutions keyed by task id with module, term, interface_term and transport_term. '
            'No independent test answers are supplied.\n' + canonical(req))
        self.s['active'] = str(job)
        self.s['calls'] += 1
        if role in ('proposer', 'reviewer', 'selector'):
            self.s['meta_calls'] += 1
        self.save()
        with (job/'watchdog.log').open('ab') as log:
            child = subprocess.Popen([PYTHON, '-m', 'machinery.study_worker', str(job)], cwd=ROOT,
                stdin=subprocess.DEVNULL, stdout=log, stderr=log, start_new_session=True, pass_fds=(self.fd,))
            write(job/'watchdog.json', {'pid': child.pid})
            while child.poll() is None:
                time.sleep(.1)
        return self.recover()

    def role_workspace(self, key, records, source=None):
        workspace = self.root/'roles'/key
        if not workspace.exists():
            copy_seed(self.study/'seed', workspace)
            if source:
                for name in inventory(source):
                    p = workspace/name
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copyfile(source/name, p)
            write(workspace/'inbox/records.json', records)
        elif read(workspace/'inbox/records.json') != records:
            raise Invalid('independent role input changed')
        return workspace

    def checked_findings(self, result, workspace, selector=False):
"""Explicit hypotheses and bounded episodes. Audit data has no input channel here."""
from .study_common import Invalid, digest, inside, sha

BASELINE = {'search': 'single revisable agenda; choose and execute next useful action',
            'memory': 'latest eight observations and full own retained history',
            'allocation': 'one bounded research invocation per round',
            'reassessment': 'revise agenda from observed results; no forced portfolio'}
EXPLORATION = {'search': 'retain competing obstacle, capability and strategy hypotheses',
               'memory': 'retain alternatives, evidence and reasons; consult own history',
               'allocation': 'consequential uncertainty trials and bounded invention episodes',
               'reassessment': 'review at committed episode horizon; permit delayed benefit'}

def validate_policy(policy):
    if set(policy) != set(BASELINE) or not all(isinstance(x, str) and 0 < len(x) <= 2000 for x in policy.values()):
        raise Invalid('policy changes may only change search/memory/allocation/reassessment guidance')

def initial(mode):
    return {'mode': mode, 'policy': BASELINE if mode == 'baseline' else EXPLORATION,
            'portfolio': {}, 'agenda': [], 'episode': None, 'decisions': [],
            'use_links': [], 'pending_policy': None, 'observations': []}

def request(state, round_index, protocol, role='researcher'):
    # Explicit projection: never serialize the full controller state or audit tree.
    return {'role': role, 'round': round_index, 'policy': state['policy'],
        'mode': state['mode'], 'agenda': state['agenda'],
        'portfolio': list(state['portfolio'].values()), 'episode': state['episode'],
        'observations': state['observations'][-8:],
        'limits': {k: protocol[k] for k in ('rounds', 'episode_rounds', 'invention_rounds', 'call_seconds')},
        'status': 'experimental; no certified continuation improvement'}

def record(state, report, workspace, round_index, protocol):
    if not isinstance(report.get('agenda'), list) or not all(isinstance(x, str) for x in report['agenda']):
        raise Invalid('agenda must be a list of strings')
    evidence = []
    for item in report.get('evidence', []):
        p = inside(workspace, item['path'])
        if not p.is_file() or sha(p) != item['sha256']:
            raise Invalid('evidence path/hash mismatch')
        if item['kind'] not in ('experiment', 'source', 'representation', 'proof_candidate', 'capability_failure'):
            raise Invalid('reports cannot self-certify a theorem')
        evidence.append(item)
    if state['mode'] != 'baseline':
        alternatives = report.get('hypotheses', [])
        if not state['portfolio'] and len(alternatives) < 2:
            raise Invalid('initial portfolio must retain competing hypotheses')
        for h in alternatives:
            if set(h) != {'id', 'kind', 'claim', 'uncertainty', 'outcomes', 'status', 'reason', 'evidence'}:
                raise Invalid('hypothesis fields invalid')
            if h['kind'] not in ('obstacle', 'capability', 'strategy') or h['status'] not in (
                    'open', 'supported_exploratorily', 'usefulness_not_demonstrated', 'refuted_by_evidence'):
                raise Invalid('invalid hypothesis category/status')
            if not h['claim'] or not h['reason']:
                raise Invalid('hypothesis needs claim and decision reason')
            if any(ref not in [e['path'] for e in evidence] for ref in h['evidence']):
                raise Invalid('hypothesis evidence not bound to actual artifacts')
            previous = state['portfolio'].get(h['id'])
            if previous and (previous['claim'], previous['kind']) != (h['claim'], h['kind']):
                raise Invalid('changed hypotheses require a new identity')
            state['portfolio'][h['id']] = h
        trial = report.get('trial')
        if not trial or trial.get('hypothesis') not in state['portfolio']:
            raise Invalid('trial must select a retained hypothesis')
        episode = state['episode']
        if episode is None or round_index > episode['review_round']:
            horizon = min(protocol['episode_rounds'], protocol['rounds'] - round_index)
            episode = {'start': round_index, 'review_round': round_index + horizon - 1,
                'continuation_rounds': horizon, 'invention_used': 0,
                'hypothesis': trial['hypothesis'], 'status': 'usefulness_not_demonstrated'}
            state['episode'] = episode
        if trial.get('invention'):
            if episode['invention_used'] >= protocol['invention_rounds']:
                raise Invalid('bounded invention allowance exhausted')
            episode['invention_used'] += 1
        else:
            h = state['portfolio'][trial['hypothesis']]
            if not h['uncertainty'] or len(h['outcomes']) < 2 or not all(
                    set(o) == {'check', 'changes_next_choice'} and all(o.values()) for o in h['outcomes']):
                raise Invalid('exploratory trial requires consequential, prospective checkable outcomes')
        state['decisions'].append({'round': round_index, 'trial': trial, 'evidence': evidence,
                                  'review_round': episode['review_round']})
    for link in report.get('use_links', []):
        if set(link) != {'artifact', 'consumer', 'claim'}:
            raise Invalid('invalid use link')
        for field in ('artifact', 'consumer'):
            if not inside(workspace, link[field]).is_file():
                raise Invalid('missing artifact-use endpoint')
        state['use_links'].append({**link, 'status': 'reported_use_pending_checked_interface'})
    proposal = report.get('policy_proposal')
    if proposal is not None:
        validate_policy(proposal)
        state['pending_policy'] = {'policy': proposal, 'hash': digest(proposal), 'proposed_round': round_index}
    state['agenda'] = report['agenda']
    state['observations'].append({'round': round_index, 'evidence': evidence,
                                  'summary': report.get('summary', ''), 'class': 'unverified_research_report'})

COMMON = '''Read MISSION.md, docs/DESIGN.md and contract.json. These supply principles and the exact target, not historical results. Construction and Agoh were historical; no proofs or agendas from them are supplied. Begin from the target definitions. This is a user-authorized experimental research study. Preserve the full published target, raw coefficients, zeros, endpoints, directions, allowed axioms and correspondence obligations. Choose your own mathematical actions: literature, experiments, representations, proof or refutation. A finite-budget failure is not unprovability. Do not use complexity, description length, compression or derived proxies in decisions. Never invoke another LLM, Codex, controllers or background processes. Do not access other workspaces, evaluation answers, audit records, Git, archives or credentials. No network shell, downloads, package updates, publication or messaging. Use .scratch for temporary files, pinned dependencies and /opt/homebrew/bin/python3. No sorry, admit, axioms or native_decide. Reports do not certify proofs. Checkpoint in research/ with unique names. Use existing artifacts; keep failed attempts. No supervisor supplies mathematical advice.'''

def prompt(req):
    if req['role'] == 'proposer':
        extra = ('Plan the next bounded trial BEFORE execution. You have read-only access to own mathematical artifacts. '
                 'Generate/retain competing explicit obstacle, capability and strategy hypotheses, not a prescribed math recipe. '
                 'Return agenda, summary, hypotheses, evidence, trial, use_links, policy_proposal and completion (null). '
                 'Each hypothesis has id, kind (obstacle/capability/strategy), claim, uncertainty, outcomes '
                 '(list of {check, changes_next_choice}), status (open/supported_exploratorily/usefulness_not_demonstrated/refuted_by_evidence), '
                 'reason, evidence (artifact paths). trial has hypothesis and invention boolean. Evidence entries have path, sha256, '
                 'kind (experiment/source/representation/proof_candidate/capability_failure). '
                 'Commit alternative observable outcomes and what changes next; invention is bounded by the episode. '
                 'Propose only guidance changes in search/memory/allocation/reassessment. No execution or invented success.')
    elif req['role'] == 'researcher':
        extra = ('Continue the single revisable agenda. Execute a bounded research action, record observations and revise agenda. '
                 'This reproduces the legacy single-worker agenda policy with empty initial history.' if req['mode'] == 'baseline' else
                 'Execute the committed_trial in this request. Its hypotheses/outcomes were recorded by a separate proposer before this call. '
                 'Return the same trial identity and hypothesis claims, with actual evidence and updated status. A bounded invention round may precede a formal root reduction. '
                 'Honor episode horizons; delayed usefulness is distinct from refutation. Policy changes are proposals for equal-budget trials.')
    else:
        extra = ('Independent reviewer: inspect actual supplied source snapshots, process receipts and checked outcomes. '
                 'Separate mathematical correctness, scope, transfer and costs. Praise or research self-reports are not evidence. '
                 'Cite artifact hashes in findings. Do not perform new research or invent retrospective holdout tasks.'
                 if req['role'] == 'reviewer' else
                 'Independent selector: consume actual checked comparison records and reviewer findings. Choose incumbent or candidate '
                 'only with cited records; unknown/failed validation cannot authorize a change. No universal score or theorem count. '
                 'A selected change is experimental, never a certified switch.')
    return COMMON + '\n' + extra + '''\nThe output envelope has request_id and payload_json (a JSON-encoded object).
Researcher payload: {agenda:[strings], summary:string, hypotheses:[{id,kind,claim,uncertainty,outcomes:[{check,changes_next_choice}],status,reason,evidence:[paths]}], evidence:[{path,sha256,kind}], trial:{hypothesis,invention}, use_links:[{artifact,consumer,claim}], policy_proposal:null or {search,memory,allocation,reassessment}, completion:null or {kind,module,declaration,correspondence}}. Baseline may return empty hypotheses and null trial.
Reviewer payload: {findings:[{path,sha256,finding}], correctness,scope,transfer,costs,recommendation}.
Selector payload: {choice:"incumbent" or "candidate",reason,evidence:[{path,sha256}]}.
REQUEST:\n''' + __import__('json').dumps(req, indent=2)
"""One-way description-burden audit. This module is never imported by policy code.

Raw bytes and zlib-9 bytes are encoding measurements, not Kolmogorov complexity.
No interpolation/smoothing or claimed sawtooth. SVG is generated with stdlib.
"""
import argparse
import html
from pathlib import Path
import time
import zlib
from .study_common import ROOT, Invalid, read, write, sha, load_state, canonical, verify_snapshot

def measured_cost(study, arm):
    root = study/'arms'/arm
    receipts = list((root/'jobs').glob('*/receipt.json'))
    validations = list((root/'evaluations').glob('*/*/*/result.json'))
    return {'subprocess_wall_seconds': sum(read(p).get('elapsed_seconds', 0) for p in receipts),
            'validation_wall_seconds': sum(read(p).get('elapsed_seconds', 0) for p in validations),
            'controller_overhead_seconds': None,
            'accounting': 'Non-overlapping worker watchdog wall plus standalone compiler/replay wall. Includes model wait and tools inside each worker. Controller overhead unknown; no CPU/token/money equivalence.'}

def measure(study, arm, artifact, dataset, reference_set, representation, marker=None, pair_id=None):
    start = time.monotonic()
    artifact, dataset = artifact.resolve(), dataset.resolve()
    if not artifact.is_relative_to(study.resolve()) or not dataset.is_relative_to(study.resolve()):
        raise Invalid('audit artifacts must be actual local study artifacts')
    raw = artifact.read_bytes()
    costs = measured_cost(study, arm)
    record = {'schema': 'math-gkm.audit.v2', 'synthetic': read(study/'protocol.json')['transport'] == 'fixture',
        'arm': arm, 'artifact': str(artifact), 'artifact_sha256': sha(artifact),
        'dataset_sha256': sha(dataset), 'reference_set': reference_set,
        'representation': representation, 'pair_id': pair_id, 'marker': marker,
        'raw_bytes': len(raw), 'zlib9_bytes': len(zlib.compress(raw, 9)),
        'cost': costs, 'cumulative_research_seconds': costs['subprocess_wall_seconds']+costs['validation_wall_seconds'],
        'cost_basis': 'worker_plus_standalone_validation_wall',
        'meaning': 'Bytes of the specified representation artifact; no estimate of shortest description or intrinsic mathematical difficulty.',
        'timestamp': time.time(), 'measurement_seconds': time.monotonic()-start}
    directory = study/'audit/raw'
    directory.mkdir(parents=True, exist_ok=True)
    write(directory/f'{time.time_ns()}.json', record)
    return record

def report(study, output):
    records = [read(p) for p in sorted((study/'audit/raw').glob('*.json'))]
    output.mkdir(parents=True, exist_ok=True)
    write(output/'raw.json', records)
    synthetic = read(study/'protocol.json')['transport'] == 'fixture' or any(r.get('synthetic') for r in records)
    title = 'SYNTHETIC FIXTURE — no mathematical progress' if synthetic else 'Observed representation burden — live artifacts'
    groups = {}
    for r in records:
        # Changing workload NEVER joins a fixed-set trajectory.
        key = (r['arm'], r['reference_set'], r['dataset_sha256'], r.get('cost_basis', 'unspecified'))
        groups.setdefault(key, []).append(r)
    width, height = 1000, 540
    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        '<rect width="100%" height="100%" fill="white"/>',
        f'<text x="30" y="30" font-size="19">{html.escape(title)}</text>',
        '<text x="30" y="53" font-size="13">Raw byte observations; no smoothing, no Kolmogorov estimate, no automatic sawtooth inference.</text>']
    if not records:
        svg.append('<text x="100" y="240" font-size="24">No measurements. No curve or improvement can be inferred.</text>')
    else:
        xmax = max(1, max(r['cumulative_research_seconds'] for r in records))
        ymax = max(1, max(r['raw_bytes'] for r in records))
        svg += ['<path d="M 90 90 V 440 H 950" fill="none" stroke="black"/>',
            '<text x="250" y="495">Cumulative measured seconds (accounting basis recorded per series)</text>',
            '<text x="10" y="80">Bytes</text>']
        colors = ['#0072B2', '#D55E00', '#009E73', '#CC79A7', '#555555']
        for index, (key, rows) in enumerate(groups.items()):
            color = colors[index % len(colors)]
            rows.sort(key=lambda r: (r['cumulative_research_seconds'], r['timestamp']))
            points = [(90+850*r['cumulative_research_seconds']/xmax, 440-340*r['raw_bytes']/ymax) for r in rows]
            if len(points) > 1:
                svg.append('<polyline fill="none" stroke="'+color+'" points="'+' '.join(f'{x:.2f},{y:.2f}' for x,y in points)+'"/>')
            for r, (x,y) in zip(rows, points):
                label = html.escape(f"{r['representation']}: {r['raw_bytes']} bytes; data {r['dataset_sha256']}; {r['cumulative_research_seconds']:.3f}s")
                svg.append(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="4" fill="{color}"><title>{label}</title></circle>')
                if r.get('marker'):
                    svg.append(f'<line x1="{x:.2f}" x2="{x:.2f}" y1="90" y2="440" stroke="{color}" stroke-dasharray="3,3"/>')
                    svg.append(f'<text x="{x+5:.2f}" y="{110+index*18}" font-size="11">{html.escape(r["marker"])}</text>')
            svg.append(f'<text x="{100+index%2*430}" y="{515+index//2*16}" font-size="9" fill="{color}">{html.escape(str(key[0:2]))} / {key[2][:8]} / {html.escape(key[3])}</text>')
    svg.append('</svg>')
    (output/'burden.svg').write_text('\n'.join(svg))
    pairs = {}
    for r in records:
        if r.get('pair_id'):
            pairs.setdefault(r['pair_id'], []).append(r)
    pair_report = []
    for name, rows in pairs.items():
        comparable = len(rows) == 2 and rows[0]['dataset_sha256'] == rows[1]['dataset_sha256'] and rows[0]['reference_set'] == rows[1]['reference_set']
        pair_report.append({'pair_id': name, 'same_data_comparable': comparable,
            'raw_byte_change': rows[1]['raw_bytes'] - rows[0]['raw_bytes'] if comparable else None})
    write(output/'paired-comparisons.json', pair_report)
    (output/'README.md').write_text(f'''# {title}

{len(records)} raw observations in {len(groups)} fixed-data groups. Fewer than two observations in a group cannot show a trend. A live-empty report deliberately shows no curve.

`raw.json` retains every unfavorable and favorable observation. `burden.svg` plots raw bytes, connects only the same arm/reference-set/data hash, and marks reported representation/strategy changes. `paired-comparisons.json` admits a drop comparison only for exactly two measurements on the same data and reference set. Changed data form separate trajectories. Connecting points is visual ordering, not interpolation evidence.

Raw bytes measure the explicitly named artifact's encoding. zlib level 9 byte counts are also saved, but are not shortest descriptions, Kolmogorov complexity, mathematical difficulty or a reward. Representation semantics and encoding choices may change; a byte drop alone proves no improvement. A sawtooth may be absent. This program neither detects nor manufactures one.

The x coordinate uses the accounting basis recorded per series: manual `measure` sums worker-watchdog wall (including provider wait/tools) and separately run validation wall; retrospective `collect` uses only actual worker receipts completed before a snapshot. These bases never join a trajectory. Neither is CPU, invoice cost, token equivalence or total elapsed calendar time. Measurement overhead is separate. Controller overhead is unknown. Provider usage remains verbatim in receipts. Prediction/transfer results remain in independently checked evaluation records; this byte plot does not imply them. Retrospective bundles measure active Lean source storage against a fixed target, not an encoding of mathematical input data; equivalence is not asserted.

Audit files are outside every live proposer filesystem grant and are absent from the policy/request projection. Do not copy this report or its derived proxies into a research request. Synthetic fixtures are not mathematical evidence.
''')
    return {'records': len(records), 'groups': len(groups), 'synthetic': synthetic, 'output': str(output)}

def collect(study):
    """Post-run observer of immutable snapshots; never called by the controller.

    The representation is an exact canonical JSON source bundle, not a compressed
    encoding of mathematical data. The fixed reference is the pinned target file.
    Reconstruct costs only from actual receipts ending before each snapshot.
    """
    collected = []
    for arm in ('baseline', 'exploration'):
        root = study/'arms'/arm
        receipts = [read(p) for p in (root/'jobs').glob('*/receipt.json')]
        previous_policy = None
        for path in sorted((root/'snapshots').iterdir()):
            manifest = verify_snapshot(path)
            start = time.monotonic()
            sources = {name: (path/'source'/name).read_text() for name in sorted(manifest['files'])
                       if name.startswith('MathGKM/') and name.endswith('.lean')}
            bundle = study/'audit/bundles'/f'{arm}-{path.name}.json'
            write(bundle, sources)
            raw = bundle.read_bytes()
            cost = sum(r.get('elapsed_seconds', 0) for r in receipts
                       if r.get('finished', float('inf')) <= manifest['created'])
            marker = 'initial representation' if previous_policy is None else (
                'strategy change' if previous_policy != manifest['policy'] else None)
            previous_policy = manifest['policy']
            record = {'schema': 'math-gkm.audit.v2', 'synthetic': read(study/'protocol.json')['transport'] == 'fixture',
                'arm': arm, 'artifact': str(bundle), 'artifact_sha256': sha(bundle),
                'dataset_sha256': sha(study/'seed/MathGKM/Markov.lean'), 'reference_set': 'fixed-pinned-target-source',
                'representation': 'canonical active MathGKM source bundle at '+path.name,
                'pair_id': None, 'marker': marker, 'raw_bytes': len(raw), 'zlib9_bytes': len(zlib.compress(raw, 9)),
                'cumulative_research_seconds': cost, 'timestamp': manifest['created'],
                'cost_basis': 'worker_wall_only_before_snapshot',
                'measurement_seconds': time.monotonic()-start,
                'cost': {'accounting': 'Only actual worker/watchdog wall completed before snapshot; excludes standalone validation and controller wall. Unknown interrupted receipts excluded, not treated as observed zero.',
                         'subprocess_wall_seconds': cost, 'validation_wall_seconds': None,
                         'controller_overhead_seconds': None},
                'meaning': 'Exact active Lean source bundle storage against fixed target bytes; excludes archived sources and non-Lean experiments. No claim that programs are equivalent or encode the dataset; no prediction/transfer inference.'}
            write(study/'audit/raw'/f'collected-{arm}-{path.name}.json', record)
            collected.append(record)
    return {'observations': len(collected), 'status': 'audit_only; no decisions affected'}

def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='command', required=True)
    plot = sub.add_parser('report')
    plot.add_argument('--study', type=Path, required=True)
    plot.add_argument('--output', type=Path, required=True)
    c = sub.add_parser('collect')
    c.add_argument('--study', type=Path, required=True)
    m = sub.add_parser('measure')
    m.add_argument('--study', type=Path, required=True)
    m.add_argument('--arm', choices=['baseline', 'exploration'], required=True)
    for flag in ('artifact', 'dataset'):
        m.add_argument('--'+flag, type=Path, required=True)
    for flag in ('reference-set', 'representation'):
        m.add_argument('--'+flag, required=True)
    m.add_argument('--marker')
    m.add_argument('--pair-id')
    a = p.parse_args()
    if a.command == 'collect':
        result = collect(a.study.resolve())
    elif a.command == 'report':
        result = report(a.study.resolve(), a.output.resolve())
    else:
        result = measure(a.study.resolve(), a.arm, a.artifact, a.dataset, a.reference_set, a.representation, a.marker, a.pair_id)
    print(canonical(result))

if __name__ == '__main__':
    main()

"""Exact-root experimental validator, separate from the small AST example gate.

General Lean elaboration is trusted code execution under the supplied execution
profile. This is not a hardened hostile-Lean admission service or switch proof.
Independent source/English review is mandatory and cannot be supplied by a worker.
"""
import json
from pathlib import Path
import re
import time
import traceback
from .engine import atomic
from .gate import digest, Rejected
from .process import run
from .trust import ROOT, LEAN, CHECKER, CORE, environment, sha

NAME = re.compile(r'[A-Za-z_][A-Za-z_0-9]*(?:\.[A-Za-z_][A-Za-z_0-9]*)*\Z')
ALLOWED = {'propext', 'Classical.choice', 'Quot.sound'}


def without_comments(text):
    """Remove nested Lean comments for conservative source screening."""
    out, i, depth = [], 0, 0
    while i < len(text):
        pair = text[i:i+2]
        if pair == '/-':
            depth += 1
            i += 2
        elif depth and pair == '-/':
            depth -= 1
            i += 2
        elif depth:
            out.append('\n' if text[i] == '\n' else ' ')
            i += 1
        elif pair == '--':
            end = text.find('\n', i)
            i = len(text) if end < 0 else end
        else:
            out.append(text[i])
            i += 1
    return ''.join(out)


def prepare(contract, claim):
    if claim.get('kind') not in ('proof', 'refutation'):
        raise Rejected('unknown completion kind')
    if any(not NAME.fullmatch(claim.get(k, '')) for k in ('module', 'declaration')):
        raise Rejected('invalid Lean name')
    if sha(ROOT/contract['root_file']) != contract['root_sha256']:
        raise Rejected('pinned root changed')
    sources, ordered, visiting = {}, [], set()

    def visit(module):
        if module in sources:
            return
        if module in visiting:
            raise Rejected('cyclic imports')
        visiting.add(module)
        path = ROOT/(module.replace('.', '/')+'.lean')
        if not path.is_file() or path.is_symlink() or not (module == 'MathGKM' or module.startswith('MathGKM.')):
            raise Rejected('completion project module must be ordinary MathGKM source')
        raw = path.read_text()
        screened = without_comments(raw)
        # Conservative lexical rejection, in addition to checked axiom closure.
        if re.search(r'\b(sorry|admit|axiom|native_decide)\b', screened):
            raise Rejected('forbidden proof construct in '+module)
        for line in screened.splitlines():
            line = line.lstrip()
            if line.startswith('import '):
                for dep in line[7:].split('--')[0].split():
                    if not NAME.fullmatch(dep):
                        raise Rejected('unsupported import syntax')
                    if dep == 'MathGKM' or dep.startswith('MathGKM.'):
                        visit(dep)
                    elif not any((p/(dep.replace('.', '/')+'.olean')).is_file() for p in dependency_paths()):
                        raise Rejected('import not in pinned dependencies: '+dep)
        visiting.remove(module)
        sources[module] = {'sha256': sha(path), 'text': raw}
        ordered.append(module)
    visit('MathGKM.Markov')
    visit(claim['module'])
    correspondence = ROOT/claim['correspondence']
    if not correspondence.resolve().is_relative_to(ROOT) or any(x in correspondence.parts for x in ('.git', '.bootstrap')):
        raise Rejected('invalid correspondence path')
    if not correspondence.is_file():
        raise Rejected('missing correspondence argument')
    binding = {'contract_hash': digest(contract), 'claim': claim,
               'sources': {m: v['sha256'] for m, v in sources.items()},
               'correspondence_sha256': sha(correspondence)}
    return {'binding': binding, 'bundle_hash': digest(binding), 'sources': sources, 'order': ordered}


def dependency_paths():
    return [CORE] + [p/'.lake/build/lib/lean' for p in sorted((ROOT/'.lake/packages').iterdir())]


def verify(contract, claim, directory, *, audit=None, stop=lambda: False):
    directory.mkdir(parents=True, exist_ok=True)
    result = {'resolved': False, 'kind': claim.get('kind'), 'checks': [], 'started': time.time()}
    try:
        bundle = prepare(contract, claim)
        result.update(bundle_hash=bundle['bundle_hash'], binding=bundle['binding'])
        atomic(directory/'bundle.json', bundle['binding'])
        source, build = directory/'source', directory/'build'
        source.mkdir(exist_ok=True)
        build.mkdir(exist_ok=True)
        env = environment([build]+dependency_paths())
        for module in bundle['order']:
            relative = Path(module.replace('.', '/'))
            path = source/relative.with_suffix('.lean')
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(bundle['sources'][module]['text'])
        wrapper = ('import '+claim['module']+'\nimport MathGKM.Markov\n'
            'theorem ControllerRootCheck : '+('Not ' if claim['kind'] == 'refutation' else '')+
            contract['root_declaration']+' := @'+claim['declaration']+'\n'
            '#print axioms ControllerRootCheck\n')
        (source/'ControllerCompletion.lean').write_text(wrapper)
        # Reject a wrong closed target before spending time on kernel replay.
        for operation in ('compile', 'kernel_replay'):
            for module in bundle['order']+['ControllerCompletion']:
                if stop():
                    raise Rejected('validation stopped')
                relative = Path(module.replace('.', '/'))
                output = build/relative.with_suffix('.olean')
                output.parent.mkdir(parents=True, exist_ok=True)
                argv = ([str(LEAN), '-j', '1', '-o', str(output), str(relative.with_suffix('.lean'))]
                        if operation == 'compile' else [str(CHECKER), module])
                record = run(argv, cwd=source, env=env, timeout=120, output_bytes=1048576)
                result['checks'].append({'module': module, 'operation': operation, **record})
                atomic(directory/'result.json', result)
                if record['returncode'] or record['termination']:
                    raise Rejected('Lean '+operation+' failed: '+module)
                if module == 'ControllerCompletion' and operation == 'compile':
                    match = re.search(r"'ControllerRootCheck' depends on axioms: \[([^\]]*)\]", record['stdout'])
                    no_axioms = "'ControllerRootCheck' does not depend on any axioms" in record['stdout']
                    if not match and not no_axioms:
                        raise Rejected('missing exact-root axiom report')
                    axioms = set(x.strip() for x in match[1].split(',') if x.strip()) if match else set()
                    if not axioms <= ALLOWED:
                        raise Rejected('unpermitted axiom closure')
                    result['axioms'] = sorted(axioms)
        if prepare(contract, claim)['bundle_hash'] != bundle['bundle_hash']:
            raise Rejected('candidate changed during validation')
        result['lean_exact_root_checked'] = True
        if not audit or audit.get('bundle_hash') != bundle['bundle_hash'] or audit.get('accepted') is not True:
            raise Rejected('independent source/English correspondence audit required for this exact bundle')
        if not isinstance(audit.get('reviewer'), str) or not audit['reviewer'].strip():
            raise Rejected('missing independent reviewer identity')
        for obligation in contract['correspondence_obligations']:
            explanation = audit.get('checks', {}).get(obligation)
            if not isinstance(explanation, str) or not explanation.strip():
                raise Rejected('undischarged source obligation: '+obligation)
        result.update(resolved=True, audit=audit, status='mathematically_resolved')
    except (Rejected, OSError, ValueError) as exc:
        result['rejection'] = str(exc)
        result['error_type'] = type(exc).__name__
        result['traceback'] = traceback.format_exc()
    result['finished'] = time.time()
    atomic(directory/'result.json', result)
    return result
"""Reuse the unchanged exact-root verifier with explicit isolated workspace binding.

The legacy source-to-root and independent correspondence requirements are not
weakened. Fixture transport cannot resolve mathematics, even with a fake audit.
"""
import argparse
from pathlib import Path
import time
from . import completion
from .study_common import Invalid, read, write, canonical, lock, digest
from .study import Arm, verify
from .study_transfer import sandbox_prefix, dependency_paths

def check(arm, claim, audit=None):
    if arm.p['transport'] == 'fixture':
        return {'resolved': False, 'rejection': 'fixture can never resolve mathematics'}
    seconds = arm.p['validation_seconds']
    if arm.s['seconds'] + seconds > arm.p['arm_seconds']:
        raise Invalid('completion validation allowance exhausted')
    key = digest({'claim': claim, 'audit': audit, 'round': arm.s['round']})
    directory = arm.root/'completion'/key
    if (directory/'result.json').exists():
        return read(directory/'result.json')
    if directory.exists():
        raise Invalid('interrupted completion validation; new independently reviewed attempt required')
    arm.s['seconds'] += seconds
    arm.save()
    directory.mkdir(parents=True)
    start = time.monotonic()
    old_root, old_run = completion.ROOT, completion.run
    prefix = sandbox_prefix(directory, dependency_paths(arm.workspace))
    def bounded(argv, **kwargs):
        remaining = seconds - (time.monotonic()-start)
        if remaining <= 0:
            raise completion.Rejected('failure within completion validation budget')
        kwargs['timeout'] = min(kwargs['timeout'], remaining)
        kwargs['env'] = {**kwargs['env'], 'TMPDIR': str(directory)}
        return old_run(prefix+argv, **kwargs)
    try:
        completion.ROOT = arm.workspace
        completion.run = bounded
        result = completion.verify(read(arm.workspace/'contract.json'), claim, directory,
                                   audit=audit, stop=arm.stopped)
    finally:
        completion.ROOT, completion.run = old_root, old_run
    if result['resolved']:
        arm.s['resolution'] = result
        arm.s['status'] = 'mathematically_resolved'
        arm.save()
    return result

def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--study', type=Path, required=True)
    p.add_argument('--arm', choices=['baseline', 'exploration'], required=True)
    p.add_argument('--claim', type=Path, required=True)
